    (rax gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s7 s9 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) fc,
  rw_cells asegs m spa (prep_locals3 b n0 ff res cur j0 j32 j128 j176) ->
  rw_cells asegs m res [C8 (Z_to_bv 64 b); C8 (Z_to_bv 64 beg); C8 (Z_to_bv 64 (b + 8)); C8 (Z_to_bv 64 bpos); C8 (Z_to_bv 64 lpos)] ->
  rw_cells asegs m (b + 8) [C8 (Z_to_bv 64 fst1); C8 (Z_to_bv 64 pe)] ->
  rw_cells asegs m cur [C8 (Z_to_bv 64 nxt); C8 (Z_to_bv 64 prv)] ->
  rw_cells asegs m (cur + 16) [C8 (Z_to_bv 64 sx)] ->
  deref_res cur beg pe bpos lpos sx = (ptr, k) -> 0 <= k -> 0 <= acc -> acc + k < 2^62 ->
  1 <= lpos < 2^62 -> 0 <= bpos < 2^62 -> 0 <= sx < 2^62 -> 0 <= beg < 2^62 -> 0 <= pe < 2^62 -> 0 <= nxt < 2^62 ->
  AIMG_TOP <= cur -> cur + 24 + sx <= aceil -> AIMG_TOP <= b -> b + 64 <= aceil -> AIMG_TOP <= res -> res + 40 <= aceil ->
  AIMG_TOP <= ff -> ff + 128 <= aceil ->
  bv_unsigned sp + -304 <= spa <= bv_unsigned sp + -288 -> spa mod 16 = 0 ->
  stk asegs m lo spa -> lo + 304 + AFS_STACK <= bv_unsigned sp -> aceil <= lo -> mem_inv asegs m -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  res mod 8 = 0 -> accessible m res 40 -> b mod 8 = 0 -> accessible m b 64 -> cur mod 8 = 0 -> accessible m cur 24 ->
  (forall (m2 : mem) (rax' y0 y1 y2 c1 c3 c4 c5 c6 c7 y3 y4 y5 y6 : word),
     munch [(lo, spa + 184)]%Z m m2 -> wmono asegs m m2 -> mem_inv asegs m2 ->
     rw_cells asegs m2 spa (prep_locals3 b n0 ff res nxt j0 j32 j128 j176) ->
     stk asegs m2 lo spa -> ACONST m2 ->
     evt asegs Q (prep_dst P_A_PREP_DTEST sp spa b ff res (acc + k) n0 rax' gp tp y0 y1 y2 (Z_to_bv 64 nxt) c1 (Z_to_bv 64 res) c3 c4 c5 c6 c7 s7 s9 s11 y3 y4 y5 y6 F fc m2)) ->
  evt asegs Q (prep_dst P_A_PREP_DLOOP sp spa b ff res acc n0 rax gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s7 s9 s11 t3 t4 t5 t6 F fc m).
