  Definition prep_tailW : list (Z * Z) :=
    [(lo, spa + 184); (res, res + 40); (ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z.

  Definition prep_tail_post (gp tp : word) (s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word) (F : bvmap 5 word) (fc : bv 32)
      (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6)
               F (ret_pc rav) fc None m' (seg_rom asegs)
      /\ munch prep_tailW m m' /\ wmono asegs m m' /\ mem_inv asegs m'
      /\ stk asegs m' lo (bv_unsigned sp)
      /\ rw_cells asegs m' res (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n))
      /\ AMBmid m' b es insz n x
      /\ as_RFS H LF0 m' /\ ACONST m' /\ stack0 m' lo shi.

  Variables (LB : list block) (s_ : as_St H) (m0 : mem).
  Hypothesis RH : as_RHEAP H s_ LB m0.
  Hypothesis AOR : aobj LB LF0 res 40.
  Hypothesis DBF : b + 64 <= ff \/ ff + 128 <= b.
  Hypothesis DRP : res + 40 <= fp \/ fp + 1 <= res.
  Hypothesis DBP : b + 64 <= fp \/ fp + 1 <= b.
  Hypothesis SEFSB : forall x' s', In (x', s') (mb_put_es es insz n x) -> x' + mb_block_size s' <= as_FSB H \/ as_FSB H + AFS_SIZE <= x'.

