    rw_cells asegs m spa (prep_locals1 b n ff j0 j32 j128 j160) ->
    rw_cells asegs m (spa + 184) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 184) ->
    rw_cells asegs m (bv_unsigned sp + -104) (prep_saves s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav) ->
    rw_cells asegs m ff (prep_ff1 ff spa fp h32 h80) ->
    rw_cells asegs m (Z.shiftr ff 3 + 2147450880) prep_sh1 ->
    rw_cells asegs m fp [C1 (b8 1)] ->
    stk asegs m lo spa -> mem_inv asegs m -> as_RFS H ((1, ff, fp) :: LF0) m -> ACONST m -> stack0 m lo shi ->
    bv_unsigned rav mod 2 = 0 ->
    evt asegs (prep_tail_post gp tp s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav F fc m)
      (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
               s2x (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 res) (Z_to_bv 64 b) s6x s7
               (Z_to_bv 64 2147450880) s9 (Z_to_bv 64 ff) (Z_to_bv 64 (ff + 64)) t3 t4 t5 t6)
